style.css:
@-moz-document domain("didattica.unipr.it") {
/* Sfondo scuro e testo chiaro */
body, html{
  background-color: #121212 !important;
}


/* Intestazioni */
h1, h2, h3, h4, h5, h6 {
  color: #ffffff !important;
}

/* ==== Navbar & Footer ==== */
.navbar, .navbar-fixed-top, .navbar-default, footer, .footer {
  background: rgba(30, 30, 30, 0.8) !important;
  color: #e0e0e0 !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.05);
}

.navbar-light .nav-link, .navbar-light .langbutton, .navbar-light .dropdown-toggle::after {
    color: white !important;
}

/* Box, card, contenitori */
.card, .box, .container, .panel, .block, .content, .region-main {
  background-color: #1c1c1c !important;
  color: #e0e0e0 !important;
  border-color: #333 !important;
}

/* Campi di input e form */
input, textarea, select {
  background-color: #2c2c2c !important;
  color: #eee !important;
  border: 1px solid #444 !important;
}

.secondary-navigation > .moremenu {
  background-color: #1c1c1c !important;
    border-radius: 12px;
}

#region-main > div {
  background-color: #1c1c1c !important;
  border-radius: 12px;
}
#region-main {
  background-color: #121212 !important;
}
.footer-header-underline {
  border-radius: 12px;
}
.container:nth-child(1) {
  border-radius: 12px;
}



/* Contenitore principale del menu */
.moremenu.navigation {
  background: rgba(28, 28, 28, 0.6) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-radius: 15px !important;
}

/* Lista del menu */

.nav {
  background-color: transparent !important;
    border-radius: 12px !important
}
.more-nav.navbar-nav {
  display: flex !important;
  gap: 10px !important;
  background: transparent !important;
  border-radius: 12px !important
}


/* Ogni voce del menu */
.nav-item {
  background: transparent !important;
  border-radius: 12px !important;
  transition: background 0.3s ease !important;
}

/* Link nel menu */
.nav-link {
  color: #d6d6d6 !important;
  padding: 10px 16px !important;
  border-radius: 12px !important;
  transition: background 0.3s ease, color 0.3s ease !important;
}

/* Hover e link attivo */
.nav-link:hover,
.nav-link[aria-current="true"] {
  background-color: rgba(255, 255, 255, 0.02) !important;
  color: #ffffff !important;
}

/* Dropdown "Altro" */
.dropdown-menu {
  background: rgba(30, 30, 30, 0.9) !important;
  border-radius: 12px !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.3) !important;
  padding: 5px 0 !important;
  margin-top: 6px !important;
}

/* Voci nel dropdown */
.dropdown-menu .dropdown-item {
  color: #b0d5f1 !important;
  padding: 10px 15px !important;
  border-radius: 8px !important;
  transition: background 0.2s ease !important;
}
.dropdown-menu .dropdown-item:hover {
  background-color: rgba(255, 255, 255, 0.07) !important;
  color: #ffffff !important;
}

/* Sticky menu in alto (facoltativo) */
.primary-navigation {
  position: sticky !important;
  top: 0 !important;
  z-index: 1000 !important;
  background-color: transparent !important;
}












.nav-link:hover {
  background-color:#151515 !important;
}

.more-nav {
    background-color: #1c1c1c !important;
}
#user-menu-toggle {
