}

.generaltable tr.emptyrow td {
  background: transparent !important;
  height: 20px !important;
  border: none !important;
}

.generaltable.boxaligncenter {
  margin-left: auto !important;
  margin-right: auto !important;
}



  
  
  
  
  
  
  
  
  

/* Ultima colonna no-border */
.generaltable td.lastcol, .generaltable th.lastcol {
  border-right: none !important;
}

/* Righe alternate con leggera differenza */
.generaltable tr:nth-child(even) td {
  background-color: rgba(35, 35, 35, 0.5) !important;
}


/* File submission (tipo conta parole.py) */
.fileuploadsubmission a {
  color: #90caf9 !important;
  font-weight: 500;
}

/* Icone dei file */
.fileuploadsubmission img.icon {
  background-color: #333 !important;
  border-radius: 6px !important;
  padding: 4px !important;
  margin-right: 6px;
  height: 24px !important;
  width: 24px !important;
}

/* Area commenti */
.comment-area textarea {
  background-color: rgba(45, 45, 45, 0.8) !important;
  color: #e0e0e0 !important;
  border: 1px solid #555 !important;
  border-radius: 8px !important;
  width: 100%;
  padding: 8px;
}

/* Pulsanti commenti */
.comment-area a {
  color: #90caf9 !important;
}









/* Sfondo semitrasparente dietro al pop-up */
.modal.moodle-has-zindex.show {
  background-color: rgba(0, 0, 0, 0.6) !important;
  backdrop-filter: blur(5px) !important;
  -webkit-backdrop-filter: blur(5px) !important;
}

/* Contenitore del pop-up */
.modal-dialog {
  background: transparent !important;
  border-radius: 16px !important;
}

/* Contenuto del pop-up */
.modal-content {
  background-color: rgba(28, 28, 28, 0.75) !important;
  backdrop-filter: blur(15px) !important;
  -webkit-backdrop-filter: blur(15px) !important;
  border-radius: 16px !important;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.5) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  color: #e0e0e0 !important;
}

/* Header del pop-up */
.modal-header {
  border-bottom: 1px solid #444 !important;
  background-color: rgba(34, 34, 34, 0.6) !important;
  border-top-left-radius: 16px !important;
  border-top-right-radius: 16px !important;
  color: #ffffff !important;
}

/* Titolo del pop-up */
.modal-title {
  font-weight: 600 !important;
  font-size: 1.2rem !important;
  color: #ffffff !important;
}

/* Pulsante di chiusura */
.modal-header .close {
  color: #ffffff !important;
  opacity: 0.8 !important;
  font-size: 1.4rem !important;
}
.modal-header .close:hover {
  opacity: 1 !important;
}

/* Corpo del pop-up */
.modal-body {
  padding: 20px !important;
  background-color: transparent !important;
  color: #cfcfcf !important;
  font-size: 15px !important;
}

/* Link "non visualizzare più" */
.modal-body a.text-muted {
  color: #999 !important;
  font-size: 0.9rem !important;
}
.modal-body a.text-muted:hover {
  color: #ccc !important;
  text-decoration: underline !important;
}

/* Bottoni */
.modal-body .btn {
  background-color: #2cdf90 !important;
  color: #03341f !important;
  border: none !important;
  border-radius: 10px !important;
  padding: 10px 16px !important;
  transition: all 0.2s ease-in-out !important;
}
.modal-body .btn:hover {
  background-color: #22af71 !important;
  color: #022d1a !important;
}

.modal-body .btn:nth-child(2) {
  background-color: rgba(28, 28, 28, 0.75)!important;
  border: 1px solid #2cdf90 !important;
  color: #2cdf90 !important
}

.modal-body .btn:nth-child(2):hover {
  background-color: rgba(50, 50, 50, 0.75)!important;
  border: 1px solid #2cdf90 !important;
  color: #2cdf90 !important
}




.navitem .btn.btn-link.p-0{
width: 20px !important;
  height: 0px !important;
    border: none !important
}


/* Contenitore generale del popover */
.popover-region-container {
  background: rgba(20, 20, 20, 0.8) !important;
  backdrop-filter: blur(12px) !important;
  -webkit-backdrop-filter: blur(12px) !important;
  border-radius: 14px !important;
  color: #e0e0e0 !important;
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.6) !important;
  border: 1px solid rgba(255, 255, 255, 0.1) !important;
  overflow: hidden !important;
}

/* Header */
.popover-region-header-container {
  background: rgba(30, 30, 30, 0.8) !important;
  color: #e0e0e0 !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
  padding: 12px 16px !important;
  display: flex !important;
  justify-content: space-between !important;
  align-items: center !important;
}

.popover-region-header-text {
  font-size: 1.1rem !important;
  font-weight: 600 !important;
  color: #ffffff !important;
  margin: 0 !important;
}

.popover-region-header-actions a {
  color: #aaa !important;
  font-size: 1rem !important;
  margin-left: 8px !important;
}
.popover-region-header-actions a:hover {
  color: #fff !important;
}

/* Corpo del popover */
.popover-region-content-container {
  padding: 12px 0 !important;
  background: transparent !important;
  color: #ccc !important;
  max-height: 400px !important;
  overflow-y: auto !important;
}

/* Singola notifica */
.content-item-container.notification {
  padding: 12px 16px !important;
  border-bottom: 1px solid rgba(255, 255, 255, 0.05) !important;
  transition: background 0.2s ease-in-out !important;
    background: rgba(30, 30, 30, 0.8) !important;
  color: #e0e0e0 !important;
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
}
.content-item-container.notification:hover {
  background-color: rgba(255, 255, 255, 0.05) !important;
}

.content-item-body {
  display: flex !important;
  align-items: center !important;
  gap: 10px !important;
}

.notification-image img {
  width: 24px !important;
  height: 24px !important;
}

.notification-message {
  font-size: 0.95rem !important;
  color: #ddd !important;
}

/* Footer della notifica (timestamp) */
.content-item-footer {
  font-size: 0.75rem !important;
  color: #888 !important;
  margin-top: 4px !important;
}

/* Link “Visualizza per intero” */
.view-more {
  display: block !important;
  margin-top: 8px !important;
  font-size: 0.85rem !important;
  color: #2cdf90 !important;
  text-decoration: none !important;
}
.view-more:hover {
  text-decoration: underline !important;
  color: #26c780 !important;
}

/* Messaggio "non hai notifiche" */
.empty-message {
  text-align: center !important;
  color: #888 !important;
  padding: 20px !important;
  font-size: 0.95rem !important;
}

/* Footer "Visualizza tutto" */
.popover-region-footer-container {
